<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Deposit', href: '/owner/deposits' }, { title: 'Settlement', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type Line = { id: number; kind: string; amount_rupiah: number; reason: string; agreement_basis: string | null; invoice: { id: number; invoice_number: string } | null; approved_at: string | null; refund_remaining_rupiah: number; can_finalize_claim: boolean; evidence: { id: number; filename: string; mime_type: string }[]; resolution: { actual_damage_amount_rupiah: number; refund_amount_rupiah: number; resolution_basis: string } | null };
    let { settlement, refund_idempotency_keys, claim_idempotency_keys }: { settlement: { id: number; deposit_account_id: number; status: string; resident: string | null; exit_inspection_notes: string; opened_at: string; day7_deadline_at: string; day30_deadline_at: string; whatsapp_notified_at: string | null; approved_at: string | null; cancelled_at: string | null; cancellation_reason: string | null; lines: Line[]; actions: { can_notify: boolean; can_approve: boolean; can_cancel: boolean } }; refund_idempotency_keys: Record<number, string>; claim_idempotency_keys: Record<number, string> } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    const label: Record<string, string> = { draft: 'Draft', approved: 'Disetujui', partially_settled: 'Sebagian diselesaikan', finalized: 'Selesai', late: 'Terlambat', cancelled: 'Dibatalkan' };
</script>

<AppHead title="Settlement deposit" />
<main class="mx-auto w-full max-w-5xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Deposit · {settlement.resident ?? 'Penyewa'}</p><h1 class="text-3xl font-semibold tracking-tight">Settlement #{settlement.id}</h1><p class="text-sm text-muted-foreground">Status: {label[settlement.status] ?? settlement.status}</p></div><Link href={`/owner/deposits/${settlement.deposit_account_id}`} class="inline-flex rounded-md border px-4 py-2 text-sm">Akun deposit</Link></header>
