            {#if line.evidence.length > 0}<div class="flex flex-wrap gap-2">{#each line.evidence as evidence (evidence.id)}<a href={`/owner/deposit-evidence/${evidence.id}`} class="rounded-md border px-3 py-1.5 text-sm text-primary underline-offset-4 hover:underline">Buka bukti · {evidence.filename}</a>{/each}</div>{/if}
            {#if line.kind === 'refund' && line.approved_at && line.refund_remaining_rupiah > 0}<Form action={`/owner/deposits/${settlement.deposit_account_id}/refunds`} method="post" class="grid gap-3 border-t pt-4 sm:grid-cols-2" enctype="multipart/form-data">{#snippet children({ errors, processing })}<input type="hidden" name="settlement_line_id" value={line.id} /><input type="hidden" name="idempotency_key" value={refund_idempotency_keys[line.id]} /><div class="sm:col-span-2"><h3 class="font-medium">Catat refund yang sudah dilakukan</h3><p class="text-sm text-muted-foreground">Sisa yang disetujui: {money(line.refund_remaining_rupiah)}. Catat setelah transfer benar-benar dikirim.</p></div><div class="space-y-2"><label for={`refund_amount_${line.id}`} class="text-sm font-medium">Nominal refund</label><Input id={`refund_amount_${line.id}`} name="amount_rupiah" type="number" min={1} max={line.refund_remaining_rupiah} step={1} required /><InputError message={errors.amount_rupiah} /></div><div class="space-y-2"><label for={`refund_date_${line.id}`} class="text-sm font-medium">Tanggal transfer</label><Input id={`refund_date_${line.id}`} name="occurred_on" type="date" required /><InputError message={errors.occurred_on} /></div><div class="space-y-2"><label for={`refund_method_${line.id}`} class="text-sm font-medium">Metode</label><select id={`refund_method_${line.id}`} name="method" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="bank_transfer">Transfer bank</option><option value="cash">Tunai</option><option value="e_wallet">Dompet digital</option><option value="other">Lainnya</option></select></div><div class="space-y-2"><label for={`refund_ref_${line.id}`} class="text-sm font-medium">Referensi transfer</label><Input id={`refund_ref_${line.id}`} name="external_reference" maxlength={160} required /></div><div class="space-y-2 sm:col-span-2"><label for={`refund_reason_${line.id}`} class="text-sm font-medium">Keterangan</label><Input id={`refund_reason_${line.id}`} name="reason" minlength={3} maxlength={1000} required /><InputError message={errors.reason} /></div><div class="space-y-2 sm:col-span-2"><label for={`refund_evidence_${line.id}`} class="text-sm font-medium">Bukti transfer aktual</label><input id={`refund_evidence_${line.id}`} name="evidence[]" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple required class="block w-full rounded-md border bg-background p-2 text-sm" /><InputError message={errors.evidence} /></div><div class="sm:col-span-2 flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Mencatat…' : 'Catat refund'}</Button></div>{/snippet}</Form>{/if}
