={`resolution_ref_${line.id}`} name="external_reference" maxlength={160} /></div><div class="space-y-2 sm:col-span-2"><label for={`resolution_evidence_${line.id}`} class="text-sm font-medium">Bukti biaya aktual dan/atau transfer refund</label><input id={`resolution_evidence_${line.id}`} name="evidence[]" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple class="block w-full rounded-md border bg-background p-2 text-sm" /><InputError message={errors.evidence} /><InputError message={errors.claim} /></div><div class="sm:col-span-2 flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Menyimpan…' : 'Finalisasi klaim'}</Button></div>{/snippet}</Form>{/if}
            {#if line.resolution}<div class="rounded-md bg-muted/40 p-3 text-sm"><p>Biaya aktual: {money(line.resolution.actual_damage_amount_rupiah)} · Refund: {money(line.resolution.refund_amount_rupiah)}</p><p class="mt-1 text-muted-foreground">{line.resolution.resolution_basis}</p></div>{/if}
        </article>{/each}</section>
    {#if settlement.actions.can_notify}<Form action={`/owner/deposit-settlements/${settlement.id}/record-whatsapp-notification`} method="post" class="rounded-xl border bg-card p-5">{#snippet children({ errors, processing })}<h2 class="font-semibold">Catat notifikasi WhatsApp manual</h2><p class="mt-1 text-sm text-muted-foreground">Aplikasi tidak mengirim pesan; pemilik mencatat setelah mengirim pernyataan settlement.</p><input type="hidden" name="confirmation" value="1" /><InputError message={errors.settlement} /><div class="mt-4 flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Saya sudah mengirim pernyataan'}</Button></div>{/snippet}</Form>{/if}
    {#if settlement.status === 'cancelled'}<section class="rounded-xl border bg-muted/40 p-5"><h2 class="font-semibold">Draft dibatalkan</h2><p class="mt-1 text-sm text-muted-foreground">{settlement.cancellation_reason ?? 'Tidak ada alasan tercatat.'}{settlement.cancelled_at ? ` · ${new Date(settlement.cancelled_at).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })}` : ''}</p><p class="mt-2 text-sm text-muted-foreground">Riwayat draft tetap tersimpan. Buat proposal pengganti dari akun deposit.</p></section>{/if}
    {#if settlement.actions.can_cancel}<Form action={`/owner/deposit-settlements/${settlement.id}/cancel`} method="post" class="rounded-xl border border-destructive/40 bg-card p-5">{#snippet children({ errors, processing })}<h2 class="font-semibold">Batalkan draft</h2><p class="mt-1 text-sm text-muted-foreground">Draft tetap disimpan sebagai histori; setelah dibatalkan, pemilik dapat membuat proposal pengganti dari akun deposit.</p><div class="mt-4 space-y-2"><label for="cancel_reason" class="text-sm font-medium">Alasan pembatalan</label><Input id="cancel_reason" name="reason" minlength={3} maxlength={1000} required /><InputError message={errors.reason} /><InputError message={errors.settlement} /></div><div class="mt-4 flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Membatalkan…' : 'Batalkan draft'}</Button></div>{/snippet}</Form>{/if}
    {#if settlement.actions.can_approve}<Form action={`/owner/deposit-settlements/${settlement.id}/approve`} method="post" class="rounded-xl border border-amber-300/60 bg-card p-5">{#snippet children({ errors, processing })}<h2 class="font-semibold">Setujui settlement</h2><p class="mt-1 text-sm text-muted-foreground">Persetujuan hanya mencatat deduction non-kas. Refund tetap harus dicatat setelah transfer aktual.</p><input type="hidden" name="confirmation" value="1" /><InputError message={errors.settlement} /><div class="mt-4 flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Menyetujui…' : 'Setujui proposal'}</Button></div>{/snippet}</Form>{/if}
</main>
